from taf.gnb.oam.ne3s.ws.interfaces import v5G19A
from taf.gnb.oam.ne3s.ws.interfaces import v5G20B
from taf.gnb.oam.ne3s.ws.interfaces.exceptions import NetactVersionNotSupported
import re


class SupportedNE3SInterfaces(object):
    v5G19A = v5G19A
    v5G20B = v5G20B


class NE3SConnectionDetails(object):
    DEFAULT_MANAGER_ID = 'EMSsim'  # Used in authentication
    DEFAULT_USERNAME = 'wsuser'  # Used to authorize the manager
    DEFAULT_PASSWORD = 'wspassword'  # Used to authorize the manager
    DEFAULT_PORT = 8080
    DEFAULT_NETACT_SERVER_ADDRESS = "192.168.255.126"
    DEFAULT_NETACT_SERVER_PORT = 8088

    def __init__(self, address, port=None, username=None, password=None, netact_server_address=None,
                 netact_server_port=None, manager_id=None, name=None):

        address = self._get_formatted_address(address)

        netact_server_address = netact_server_address or self.DEFAULT_NETACT_SERVER_ADDRESS
        netact_server_address = self._get_formatted_address(netact_server_address)

        self.address = address
        self.port = port or self.DEFAULT_PORT
        self.username = username or self.DEFAULT_USERNAME
        self.password = password or self.DEFAULT_PASSWORD
        self.manager_id = manager_id or self.DEFAULT_MANAGER_ID
        self.netact_server_port = netact_server_port or self.DEFAULT_NETACT_SERVER_PORT
        self.netact_server_address = netact_server_address
        self.name = name or "default"

    def _get_formatted_address(self, netact_server_address):
        if 'http' in netact_server_address:
            address_match = re.match(r'http.?:\/\/(?P<ip_addr>[\w.]+)\/*',
                                     netact_server_address)
            if address_match is None:
                err_msg = "Provided address value {value} is invalid, " \
                          "should be plain ip addr or http://<ip-addr>"
                raise ValueError(err_msg.format(value=netact_server_address))
            netact_server_address = address_match.group("ip_addr")
        return netact_server_address


class NE3SProvider(object):

    @classmethod
    def provide_interface(cls,
                          address,
                          port=None,
                          username=None,
                          password=None,
                          netact_server_address=None,
                          netact_server_port=None,
                          manager_id=None,
                          name=None,
                          netact_version='v5G20B'):
        connection_details = NE3SConnectionDetails(
            address=address,
            port=port,
            username=username,
            password=password,
            netact_server_address=netact_server_address,
            netact_server_port=netact_server_port,
            manager_id=manager_id,
            name=name
        )

        netact_type = getattr(SupportedNE3SInterfaces, netact_version, None)
        if not netact_type:
            exception_message = 'Version {} of NetAct is not supported'.format(netact_version)
            raise NetactVersionNotSupported(exception_message)
        return netact_type(connection_details=connection_details)
